    };
    await expect(refreshPrices(lines, fetcher)).rejects.toThrow("fetch failed");
  });

  it("returns empty array for empty lines", async () => {
    const fetcher: PriceFetcher = {
      fetchPriceCents: vi.fn(),
    };
    const refreshed = await refreshPrices([], fetcher);
    expect(refreshed).toEqual([]);
    expect(fetcher.fetchPriceCents).not.toHaveBeenCalled();
  });
});

import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
} from "../src/pricing.ts";
import { RegionalTaxCalculator, NoTaxCalculator } from "../src/tax.ts";
import {
  FlatShippingCalculator,
  FreeShippingCalculator,
} from "../src/shipping.ts";
import { InventoryError } from "../src/inventory.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";
import type { PriceFetcher, InventoryChecker } from "../src/inventory.ts";
import type { AsyncTaxRateProvider } from "../src/tax.ts";

const product = (
  id: string,
  priceCents: number,
  weightGrams?: number,
): Product => ({
  id,
  name: `Product ${id}`,
  unitPriceCents: priceCents,
  weightGrams,
});

describe("Cart — line management", () => {
  it("adds a product and tracks item count", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 2);
    expect(cart.itemCount).toBe(2);
  });

  it("merges quantities when adding the same product", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 2);
    cart.add(product("a", 1_000), 3);
    expect(cart.itemCount).toBe(5);
  });

  it("rejects non-positive quantity on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", 1_000), 0)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1_000), -1)).toThrow(RangeError);
    expect(() => cart.add(product("a", 1_000), 1.5)).toThrow(RangeError);
  });

  it("rejects negative unitPriceCents on add", () => {
    const cart = new Cart();
    expect(() => cart.add(product("a", -1), 1)).toThrow(RangeError);
  });

  it("removes a product and returns true", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("returns false when removing an unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("nonexistent")).toBe(false);
  });

  it("updateQuantity sets new quantity", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 3);
    cart.updateQuantity("a", 1);
    expect(cart.itemCount).toBe(1);
  });

  it("updateQuantity 0 removes the product", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
    expect(cart.remove("a")).toBe(false);
  });

  it("updateQuantity rejects negative", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("updateQuantity rejects non-integer", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    expect(() => cart.updateQuantity("a", 1.5)).toThrow(RangeError);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("x", 5)).toThrow("not in the cart");
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    cart.add(product("b", 2_000), 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns a deep copy", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 2);
    const snap = cart.snapshot();
    expect(snap).toHaveLength(1);
    expect(snap[0]!.product.id).toBe("a");
    expect(snap[0]!.quantity).toBe(2);
    // Mutating snapshot should not affect cart
    (snap[0] as { quantity: number }).quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart — pricing pipeline (totals)", () => {
  it("computes subtotal as sum of (price × quantity)", () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 2);
    cart.add(product("b", 500), 3);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(3_500);
  });

  it("empty cart has all-zero totals", () => {
    const cart = new Cart();
    const t = cart.totals();
    expect(t).toEqual({
      subtotalCents: 0,
      discountCents: 0,
      taxCents: 0,
      shippingCents: 0,
      totalCents: 0,
    });
  });

  it("applies discount, then computes tax on discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(10),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.1 }),
      region: "US",
    });
    cart.add(product("a", 10_000), 1);
    const t = cart.totals();
    expect(t.subtotalCents).toBe(10_000);
    expect(t.discountCents).toBe(1_000); // 10% of 10000
    expect(t.taxCents).toBe(900); // 10% of (10000 - 1000)
  });

  it("clamps discount to [0, subtotal]", () => {
    const overPolicy: DiscountPolicy = {
      computeDiscountCents: () => 999_999,
    };
    const cart = new Cart({ discountPolicy: overPolicy });
    cart.add(product("a", 1_000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(1_000);
    expect(t.totalCents).toBe(0);
  });

  it("clamps negative discount to 0", () => {
    const negPolicy: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: negPolicy });
    cart.add(product("a", 1_000), 1);
    const t = cart.totals();
    expect(t.discountCents).toBe(0);
    expect(t.totalCents).toBe(1_000);
  });

  it("shipping is computed against the discounted subtotal", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(4_000),
      shippingCalculator: new FlatShippingCalculator(500, 5_000),
    });
    cart.add(product("a", 8_000), 1);
    const t = cart.totals();
    // discounted subtotal = 8000 - 4000 = 4000, below 5000 threshold → flat 500
    expect(t.shippingCents).toBe(500);
  });

  it("totalCents = discountedSubtotal + tax + shipping", () => {
    const cart = new Cart({
      discountPolicy: new FixedAmountDiscountPolicy(200),
      taxCalculator: new RegionalTaxCalculator({ "US": 0.05 }),
      shippingCalculator: new FlatShippingCalculator(300),
      region: "US",
    });
    cart.add(product("a", 1_000), 1);
    const t = cart.totals();
    const discountedSub = 1_000 - 200;
    const tax = Math.floor(discountedSub * 0.05);
    expect(t.totalCents).toBe(discountedSub + tax + 300);
  });

  it("uses defaults when no config is given", () => {
    const cart = new Cart();
    cart.add(product("a", 500), 2);
    const t = cart.totals();
    // defaults: NoDiscount, NoTax, FreeShipping
    expect(t.discountCents).toBe(0);
    expect(t.taxCents).toBe(0);
    expect(t.shippingCents).toBe(0);
    expect(t.totalCents).toBe(1_000);
  });

  it("negative tax from calculator is clamped to 0", () => {
    const negTax: TaxCalculator = {
      computeTaxCents: () => -100,
    };
    const cart = new Cart({ taxCalculator: negTax });
    cart.add(product("a", 1_000), 1);
    expect(cart.totals().taxCents).toBe(0);
  });

  it("negative shipping from calculator is clamped to 0", () => {
    const negShipping: ShippingCalculator = {
      computeShippingCents: () => -100,
    };
    const cart = new Cart({ shippingCalculator: negShipping });
    cart.add(product("a", 1_000), 1);
    expect(cart.totals().shippingCents).toBe(0);
  });
});

describe("Cart — async checkout", () => {
  it("returns totals and lines without collaborators", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    const result = await cart.checkout();
    expect(result.totals.subtotalCents).toBe(1_000);
    expect(result.lines).toHaveLength(1);
  });

  it("refreshes prices from priceFetcher", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(2_000),
    };
    const result = await cart.checkout({ priceFetcher });
    expect(result.totals.subtotalCents).toBe(2_000);
    expect(result.lines[0]!.product.unitPriceCents).toBe(2_000);
  });

  it("throws InventoryError when item is unavailable", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 5);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: false, reason: "sold out" }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(5);
      expect(err.message).toBe("sold out");
    }
  });

  it("throws InventoryError on partial-stock denial", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 10);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 3,
      }),
    };
    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      const err = e as InventoryError;
      expect(err.productId).toBe("a");
      expect(err.requested).toBe(10);
      expect(err.available).toBe(3);
    }
  });

  it("passes when inventory is available", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2_000);
  });

  it("passes with availableQuantity >= requested", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 2);
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({
        available: true,
        availableQuantity: 5,
      }),
    };
    const result = await cart.checkout({ inventoryChecker });
    expect(result.totals.subtotalCents).toBe(2_000);
  });

  it("uses asyncTaxProvider when supplied", async () => {
    const cart = new Cart({
      discountPolicy: new NoDiscountPolicy(),
      region: "US",
    });
    cart.add(product("a", 10_000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.08),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    expect(result.totals.taxCents).toBe(800);
    expect(asyncTaxProvider.getRate).toHaveBeenCalledWith("US");
  });

  it("composes discount + asyncTax + shipping in checkout", async () => {
    const cart = new Cart({
      discountPolicy: new PercentageDiscountPolicy(20),
      shippingCalculator: new FlatShippingCalculator(500),
      region: "US-CA",
    });
    cart.add(product("a", 5_000), 2); // subtotal = 10000
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockResolvedValue(0.1),
    };
    const result = await cart.checkout({ asyncTaxProvider });
    // discount: 20% of 10000 = 2000
    expect(result.totals.discountCents).toBe(2_000);
    // discounted subtotal: 8000
    // tax: 10% of 8000 = 800
    expect(result.totals.taxCents).toBe(800);
    expect(result.totals.shippingCents).toBe(500);
    expect(result.totals.totalCents).toBe(8_000 + 800 + 500);
  });

  it("asyncTaxProvider rejection propagates", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    const asyncTaxProvider: AsyncTaxRateProvider = {
      getRate: vi.fn().mockRejectedValue(new Error("rate service down")),
    };
    await expect(cart.checkout({ asyncTaxProvider })).rejects.toThrow(
      "rate service down",
    );
  });

  it("priceFetcher rejection propagates", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi
        .fn()
        .mockRejectedValue(new Error("price service error")),
    };
    await expect(cart.checkout({ priceFetcher })).rejects.toThrow(
      "price service error",
    );
  });

  it("price refresh happens before inventory check", async () => {
    const callOrder: string[] = [];
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);

    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockImplementation(async () => {
        callOrder.push("price");
        return 2_000;
      }),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockImplementation(async () => {
        callOrder.push("inventory");
        return { available: true };
      }),
    };
    await cart.checkout({ priceFetcher, inventoryChecker });
    expect(callOrder).toEqual(["price", "inventory"]);
  });

  it("inventory check uses refreshed prices in lines", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    const priceFetcher: PriceFetcher = {
      fetchPriceCents: vi.fn().mockResolvedValue(3_000),
    };
    const inventoryChecker: InventoryChecker = {
      check: vi.fn().mockResolvedValue({ available: true }),
    };
    const result = await cart.checkout({ priceFetcher, inventoryChecker });
    expect(result.totals.subtotalCents).toBe(3_000);
  });

  it("first failing inventory item wins", async () => {
    const cart = new Cart();
    cart.add(product("a", 1_000), 1);
    cart.add(product("b", 2_000), 1);

    const inventoryChecker: InventoryChecker = {
      check: vi
        .fn()
        .mockResolvedValueOnce({ available: true })
        .mockResolvedValueOnce({ available: false, reason: "b is out" }),
    };

    try {
      await cart.checkout({ inventoryChecker });
      expect.unreachable("should have thrown");
    } catch (e) {
      expect(e).toBeInstanceOf(InventoryError);
      expect((e as InventoryError).productId).toBe("b");
    }
  });

  it("checkout with empty cart returns zero totals", async () => {
    const cart = new Cart();
    const result = await cart.checkout();
    expect(result.totals.totalCents).toBe(0);
    expect(result.lines).toHaveLength(0);
  });

  it("uses sync tax calculator when no asyncTaxProvider", async () => {
    const cart = new Cart({
      taxCalculator: new RegionalTaxCalculator({ "US": 0.05 }),
      region: "US",
    });
    cart.add(product("a", 10_000), 1);
    const result = await cart.checkout();
    expect(result.totals.taxCents).toBe(500);
  });
});

import { describe, it, expect } from "vitest";
import {
  NoDiscountPolicy,
  PercentageDiscountPolicy,
  FixedAmountDiscountPolicy,
  CompositeDiscountPolicy,
} from "../src/pricing.ts";

describe("NoDiscountPolicy", () => {
  const policy = new NoDiscountPolicy();

  it("returns 0 for a positive subtotal", () => {
    expect(policy.computeDiscountCents(10_000)).toBe(0);
  });

  it("returns 0 for zero subtotal", () => {
    expect(policy.computeDiscountCents(0)).toBe(0);
  });

  it("returns 0 for a negative subtotal", () => {
    expect(policy.computeDiscountCents(-500)).toBe(0);
  });
});

describe("PercentageDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative percent", () => {
      expect(() => new PercentageDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects percent above 100", () => {
      expect(() => new PercentageDiscountPolicy(101)).toThrow(RangeError);
    });

    it("rejects NaN", () => {
      expect(() => new PercentageDiscountPolicy(NaN)).toThrow(RangeError);
    });

    it("rejects Infinity", () => {
      expect(() => new PercentageDiscountPolicy(Infinity)).toThrow(RangeError);
    });

    it("accepts 0%", () => {
      expect(() => new PercentageDiscountPolicy(0)).not.toThrow();
    });

    it("accepts 100%", () => {
      expect(() => new PercentageDiscountPolicy(100)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("computes 10% of 10000 as 1000", () => {
      const policy = new PercentageDiscountPolicy(10);
      expect(policy.computeDiscountCents(10_000)).toBe(1_000);
    });

    it("rounds down to nearest cent", () => {
      const policy = new PercentageDiscountPolicy(33);
      // 33% of 100 = 33.0
      expect(policy.computeDiscountCents(100)).toBe(33);
      // 33% of 101 = 33.33 → floor to 33
      expect(policy.computeDiscountCents(101)).toBe(33);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new PercentageDiscountPolicy(50);
      expect(policy.computeDiscountCents(-1000)).toBe(0);
    });

    it("100% returns the entire subtotal", () => {
      const policy = new PercentageDiscountPolicy(100);
      expect(policy.computeDiscountCents(5_000)).toBe(5_000);
    });

    it("0% returns 0", () => {
      const policy = new PercentageDiscountPolicy(0);
      expect(policy.computeDiscountCents(5_000)).toBe(0);
    });

    it("handles very large subtotals", () => {
      const policy = new PercentageDiscountPolicy(15);
      expect(policy.computeDiscountCents(999_999_99)).toBe(
        Math.floor((999_999_99 * 15) / 100),
      );
    });
  });
});

describe("FixedAmountDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects negative amount", () => {
      expect(() => new FixedAmountDiscountPolicy(-1)).toThrow(RangeError);
    });

    it("rejects non-integer amount", () => {
      expect(() => new FixedAmountDiscountPolicy(10.5)).toThrow(RangeError);
    });

    it("accepts 0", () => {
      expect(() => new FixedAmountDiscountPolicy(0)).not.toThrow();
    });
  });

  describe("computeDiscountCents", () => {
    it("returns the fixed amount when subtotal is larger", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(10_000)).toBe(500);
    });

    it("caps at subtotal when fixed amount exceeds subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(5_000);
      expect(policy.computeDiscountCents(3_000)).toBe(3_000);
    });

    it("returns subtotal when amounts are equal", () => {
      const policy = new FixedAmountDiscountPolicy(1_000);
      expect(policy.computeDiscountCents(1_000)).toBe(1_000);
    });

    it("returns 0 for zero subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const policy = new FixedAmountDiscountPolicy(500);
      expect(policy.computeDiscountCents(-100)).toBe(0);
    });

    it("0-cent discount always returns 0", () => {
      const policy = new FixedAmountDiscountPolicy(0);
      expect(policy.computeDiscountCents(5_000)).toBe(0);
    });
  });
});

describe("CompositeDiscountPolicy", () => {
  describe("constructor validation", () => {
    it("rejects empty policy list", () => {
      expect(() => new CompositeDiscountPolicy([])).toThrow(
        "at least one policy",
      );
    });
  });

  describe("sum mode", () => {
    it("sums discounts from all child policies against the original subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      // 10% of 5000 = 500, plus fixed 200 = 700
      expect(composite.computeDiscountCents(5_000)).toBe(700);
    });

    it("clamps negative child results to 0 before summing", () => {
      const negativePolicy = {
        computeDiscountCents: () => -100,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(300)],
        "sum",
      );
      // max(0, -100) + 300 = 300
      expect(composite.computeDiscountCents(5_000)).toBe(300);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "sum",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });

    it("returns 0 for negative subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "sum",
      );
      expect(composite.computeDiscountCents(-500)).toBe(0);
    });

    it("can exceed subtotal (caller clamps)", () => {
      const composite = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(3_000), new FixedAmountDiscountPolicy(3_000)],
        "sum",
      );
      // sum mode: min(3000, 5000) + min(3000, 5000) = 6000 (exceeds 5000)
      expect(composite.computeDiscountCents(5_000)).toBe(6_000);
    });

    it("defaults to sum mode when mode is omitted", () => {
      const composite = new CompositeDiscountPolicy([
        new FixedAmountDiscountPolicy(100),
        new FixedAmountDiscountPolicy(200),
      ]);
      expect(composite.computeDiscountCents(1_000)).toBe(300);
    });
  });

  describe("chain mode", () => {
    it("applies discounts sequentially on remaining subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(50), new PercentageDiscountPolicy(50)],
        "chain",
      );
      // 50% of 1000 = 500 → remaining 500 → 50% of 500 = 250 → total discount 750
      expect(composite.computeDiscountCents(1_000)).toBe(750);
    });

    it("stops accumulating when remaining reaches 0", () => {
      const composite = new CompositeDiscountPolicy(
        [
          new FixedAmountDiscountPolicy(5_000),
          new FixedAmountDiscountPolicy(5_000),
        ],
        "chain",
      );
      // first eats 3000 (clamped to remaining), second has 0 remaining
      expect(composite.computeDiscountCents(3_000)).toBe(3_000);
    });

    it("ordering matters in chain mode", () => {
      const policyA = new CompositeDiscountPolicy(
        [new FixedAmountDiscountPolicy(200), new PercentageDiscountPolicy(10)],
        "chain",
      );
      const policyB = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10), new FixedAmountDiscountPolicy(200)],
        "chain",
      );
      const subtotal = 5_000;
      const resultA = policyA.computeDiscountCents(subtotal);
      const resultB = policyB.computeDiscountCents(subtotal);
      // A: 200 off → remaining 4800 → 10% of 4800 = 480 → total 680
      expect(resultA).toBe(680);
      // B: 10% of 5000 = 500 → remaining 4500 → min(200,4500) = 200 → total 700
      expect(resultB).toBe(700);
      expect(resultA).not.toBe(resultB);
    });

    it("clamps negative child results to 0 in chain mode", () => {
      const negativePolicy = {
        computeDiscountCents: () => -500,
      };
      const composite = new CompositeDiscountPolicy(
        [negativePolicy, new FixedAmountDiscountPolicy(100)],
        "chain",
      );
      // max(0, -500) clamped to min(0, 5000) = 0 → remaining stays 5000 → 100
      expect(composite.computeDiscountCents(5_000)).toBe(100);
    });

    it("returns 0 for zero subtotal", () => {
      const composite = new CompositeDiscountPolicy(
        [new PercentageDiscountPolicy(10)],
        "chain",
      );
      expect(composite.computeDiscountCents(0)).toBe(0);
    });
  });
});

