import { describe, it, expect } from "vitest";
import {
  FreeShippingCalculator,
  FlatShippingCalculator,
  WeightBasedShippingCalculator,
} from "../src/shipping.ts";
import type { CartLine } from "../src/product.ts";

const makeLine = (
  id: string,
  weightGrams: number | undefined,
  quantity: number,
): CartLine => ({
  product: { id, name: id, unitPriceCents: 1_000, weightGrams },
  quantity,
});

describe("FreeShippingCalculator", () => {
  const calc = new FreeShippingCalculator();

  it("returns 0 for non-empty cart", () => {
    expect(calc.computeShippingCents([makeLine("a", 500, 1)], 5_000)).toBe(0);
  });

  it("returns 0 for empty cart", () => {
    expect(calc.computeShippingCents([], 0)).toBe(0);
  });
});

describe("FlatShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects negative flatCents", () => {
      expect(() => new FlatShippingCalculator(-1)).toThrow(RangeError);
    });

    it("rejects non-integer flatCents", () => {
      expect(() => new FlatShippingCalculator(5.5)).toThrow(RangeError);
    });

    it("rejects negative freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, -1)).toThrow(RangeError);
    });

    it("rejects non-integer freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 99.9)).toThrow(RangeError);
    });

    it("accepts 0 for flatCents", () => {
      expect(() => new FlatShippingCalculator(0)).not.toThrow();
    });

    it("accepts 0 for freeOverCents", () => {
      expect(() => new FlatShippingCalculator(500, 0)).not.toThrow();
    });
  });

  describe("computeShippingCents", () => {
    it("returns flat rate for non-empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 2_000)).toBe(
        599,
      );
    });

    it("returns 0 for empty cart", () => {
      const calc = new FlatShippingCalculator(599);
      expect(calc.computeShippingCents([], 0)).toBe(0);
    });

    it("returns 0 when subtotal meets the free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5_000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 5_000)).toBe(0);
    });

    it("returns 0 when subtotal exceeds the free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5_000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 10_000)).toBe(
        0,
      );
    });

    it("returns flat rate when subtotal is below the free-over threshold", () => {
      const calc = new FlatShippingCalculator(599, 5_000);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 4_999)).toBe(
        599,
      );
    });

    it("returns flat rate when no threshold is configured", () => {
      const calc = new FlatShippingCalculator(599);
      expect(
        calc.computeShippingCents([makeLine("a", 100, 1)], 100_000),
      ).toBe(599);
    });

    it("threshold of 0 means always free for non-empty carts", () => {
      const calc = new FlatShippingCalculator(599, 0);
      expect(calc.computeShippingCents([makeLine("a", 100, 1)], 0)).toBe(0);
    });
  });
});

describe("WeightBasedShippingCalculator", () => {
  describe("constructor validation", () => {
    it("rejects empty bracket list", () => {
      expect(() => new WeightBasedShippingCalculator([])).toThrow(
        "at least one weight bracket",
      );
    });

    it("rejects bracket with zero upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 0, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: -1, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer upToGrams", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1.5, costCents: 500 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with negative costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: -1 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects bracket with non-integer costCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator([
            { upToGrams: 1000, costCents: 5.5 },
          ]),
      ).toThrow(RangeError);
    });

    it("rejects negative overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            -1,
          ),
      ).toThrow(RangeError);
    });

    it("rejects non-integer overflowCostCents", () => {
      expect(
        () =>
          new WeightBasedShippingCalculator(
            [{ upToGrams: 1000, costCents: 500 }],
            5.5,
          ),
      ).toThrow(RangeError);
    });
  });

  describe("computeShippingCents", () => {
    const brackets = [
      { upToGrams: 500, costCents: 300 },
      { upToGrams: 2000, costCents: 700 },
      { upToGrams: 5000, costCents: 1200 },
    ];

    it("returns 0 for empty cart", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(calc.computeShippingCents([], 5_000)).toBe(0);
    });

    it("returns 0 when all products have no weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", undefined, 2)], 5_000),
      ).toBe(0);
    });

    it("selects the first bracket that covers the weight", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 400, 1)], 5_000),
      ).toBe(300);
    });

    it("uses the bracket at the exact boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 500, 1)], 5_000),
      ).toBe(300);
    });

    it("moves to next bracket when weight exceeds boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 501, 1)], 5_000),
      ).toBe(700);
    });

    it("selects the heaviest bracket at its boundary", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 5000, 1)], 5_000),
      ).toBe(1200);
    });

    it("uses overflow cost when weight exceeds all brackets", () => {
      const calc = new WeightBasedShippingCalculator(brackets, 2_000);
      expect(
        calc.computeShippingCents([makeLine("a", 5001, 1)], 5_000),
      ).toBe(2_000);
    });

    it("falls back to heaviest bracket cost when no overflow is specified", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      expect(
        calc.computeShippingCents([makeLine("a", 10_000, 1)], 5_000),
      ).toBe(1200);
    });

    it("sums weight across multiple lines and quantities", () => {
      const calc = new WeightBasedShippingCalculator(brackets);
      // 300g × 2 + 500g × 1 = 1100g → second bracket (≤2000g) = 700
      const lines = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
      expect(calc.computeShippingCents(lines, 5_000)).toBe(700);
    });

    it("sorts brackets regardless of input order", () => {
      const unordered = [
        { upToGrams: 5000, costCents: 1200 },
        { upToGrams: 500, costCents: 300 },
        { upToGrams: 2000, costCents: 700 },
      ];
      const calc = new WeightBasedShippingCalculator(unordered);
      expect(
        calc.computeShippingCents([makeLine("a", 400, 1)], 5_000),
      ).toBe(300);
    });
  });
});

