+      expect(
+        calc.computeShippingCents([makeLine("a", 10_000, 1)], 5_000),
+      ).toBe(1200);
+    });
+
+    it("sums weight across multiple lines and quantities", () => {
+      const calc = new WeightBasedShippingCalculator(brackets);
+      // 300g × 2 + 500g × 1 = 1100g → second bracket (≤2000g) = 700
+      const lines = [makeLine("a", 300, 2), makeLine("b", 500, 1)];
+      expect(calc.computeShippingCents(lines, 5_000)).toBe(700);
